   ],
   "source": [
    "rng = np.random.RandomState(0)\n",
    "n = 400\n",
    "df = pd.DataFrame({\n",
    "    'tenure': rng.randint(1, 72, n),\n",
    "    'monthly': rng.uniform(20, 120, n).round(2),\n",
    "    'plan': rng.choice(['basic', 'plus', 'pro'], n),\n",
    "})\n",
    "df['churn'] = ((df['monthly'] > 80) & (df['tenure'] < 24)).astype(int)\n",
    "print(df.shape)\n",
    "print(df['churn'].mean())"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 3,
