    }
   ],
   "source": [
    "late_signups = pd.DataFrame({'tenure': [2, 3], 'monthly': [99.0, 110.0], 'plan': ['pro', 'pro'], 'churn': [1, 1]})\n",
    "df = pd.concat([df, late_signups], ignore_index=True)\n",
    "print(len(df))"
   ]
  },
  {
