   ],
   "source": [
    "enc = OneHotEncoder(sparse_output=False)\n",
    "plan_onehot = enc.fit_transform(df[['plan']])\n",
    "print(plan_onehot.shape)\n",
    "print(list(enc.categories_[0]))"
   ]
  },
  {
   "cell_type": "code",
